import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOrbitron = makeLoadFont('Orbitron');

// Load futuristic font at module level
const { fontFamily: orbitronFamily } = loadOrbitron();



export type SciFiPopupProps = Record<string, any>;

const SciFiPopup: React.FC<SciFiPopupProps> = ({
  backgroundColor = "#020603",
  transparentBackground = true,
  durationInSeconds = 5,
  message = "ACCESS GRANTED",
  primaryColor = "#4ade80", // Neon green default
  glowIntensity = 1.2,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationFrames = durationInSeconds * fps;

  // Background handling
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timing constants
  const outStartFrame = durationFrames - 30; // Start exiting 1 second before end
  const clampedFrame = Math.max(0, Math.min(frame, durationFrames));

  // --- Animation Logic ---

  // 1. Horizontal "Beam" effect (expands X)
  const beamIn = spring({
    frame: clampedFrame,
    fps,
    config: { damping: 14, stiffness: 120 },
  });
  
  const beamOut = spring({
    frame: Math.max(0, clampedFrame - outStartFrame - 10), // Staggered exit
    fps,
    config: { damping: 14, stiffness: 120 },
  });

  // 2. Vertical "Open" effect (expands Y)
  const openIn = spring({
    frame: Math.max(0, clampedFrame - 10), // Wait for beam to start
    fps,
    config: { damping: 12, stiffness: 90 },
  });

  const openOut = spring({
    frame: Math.max(0, clampedFrame - outStartFrame), // Closes first
    fps,
    config: { damping: 12, stiffness: 90 },
  });

  // Combine springs for current scale, ensuring they don't dip below 0
  const scaleX = Math.max(0, beamIn - beamOut);
  const scaleY = Math.max(0, openIn - openOut);

  // 3. Text Glitch/Flicker Reveal
  const isOutro = clampedFrame >= outStartFrame;
  const textOpacity = isOutro
    ? interpolate(clampedFrame, [outStartFrame, outStartFrame + 5], [1, 0], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      })
    : interpolate(
        clampedFrame,
        [15, 16, 17, 19, 21, 25],
        [0, 0.8, 0.2, 1, 0.6, 1],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      );

  // 4. Subtle continuous pulse during active state
  const pulseScale = interpolate(
    Math.sin(frame * 0.1),
    [-1, 1],
    [0.98, 1.02]
  );
  
  // Apply pulse only when fully open and not exiting
  const finalScaleX = scaleX * (scaleX > 0.9 && !isOutro ? pulseScale : 1);
  const finalScaleY = scaleY * (scaleY > 0.9 && !isOutro ? pulseScale : 1);

  // Responsive sizing
  const bannerWidth = width * 0.6;
  const bannerHeight = height * 0.18;
  const dynamicFontSize = Math.min(width * 0.045, 80);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      
      {/* Main Animated Wrapper */}
      <div
        style={{
          position: "relative",
          width: bannerWidth,
          height: bannerHeight,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${finalScaleX}, ${finalScaleY})`,
          transformOrigin: "center center",
          transition: "none",
        }}
      >
        {/* Layer 1: Outer Faded Glow Band (Simulating depth and light bleed) */}
        <div
          style={{
            position: "absolute",
            inset: "-10% -20%", // Extend slightly beyond bounds for soft edge
            background: `linear-gradient(90deg, transparent 0%, ${primaryColor}40 20%, ${primaryColor}80 50%, ${primaryColor}40 80%, transparent 100%)`,
            filter: `blur(${15 * glowIntensity}px)`,
            opacity: 0.8,
            transition: "none",
          }}
        />

        {/* Layer 2: Inner Solid Tech Band */}
        <div
          style={{
            position: "absolute",
            left: "5%",
            right: "5%",
            top: "22%",
            bottom: "22%",
            backgroundColor: `${primaryColor}A6`, // ~65% opacity
            boxShadow: `0 0 ${12 * glowIntensity}px ${primaryColor}, inset 0 0 10px rgba(255,255,255,0.2)`,
            transition: "none",
          }}
        />

        {/* Layer 3: Tech Scanlines Overlay for authentic screen feel */}
        <div
          style={{
            position: "absolute",
            left: "5%",
            right: "5%",
            top: "22%",
            bottom: "22%",
            background: `repeating-linear-gradient(
              0deg,
              transparent,
              transparent 2px,
              rgba(0,0,0,0.2) 2px,
              rgba(0,0,0,0.2) 4px
            )`,
            zIndex: 5,
            pointerEvents: "none",
            transition: "none",
          }}
        />

        {/* Layer 4: Structural Accent Lines (White details) */}
        {/* Top left broken line */}
        <div style={{ position: "absolute", top: "15%", left: "12%", width: "18%", height: 3, backgroundColor: "white", opacity: 0.9, boxShadow: `0 0 5px white` }} />
        {/* Top right small line */}
        <div style={{ position: "absolute", top: "15%", right: "22%", width: "6%", height: 3, backgroundColor: "white", opacity: 0.9, boxShadow: `0 0 5px white` }} />
        
        {/* Bottom right broken line */}
        <div style={{ position: "absolute", bottom: "15%", right: "12%", width: "22%", height: 3, backgroundColor: "white", opacity: 0.9, boxShadow: `0 0 5px white` }} />
        {/* Bottom left small line */}
        <div style={{ position: "absolute", bottom: "15%", left: "28%", width: "4%", height: 3, backgroundColor: "white", opacity: 0.9, boxShadow: `0 0 5px white` }} />

        {/* Layer 5: Text */}
        <div
          style={{
            position: "relative",
            zIndex: 10,
            fontFamily: orbitronFamily,
            fontSize: dynamicFontSize,
            fontWeight: 700,
            color: "white",
            letterSpacing: "0.2em",
            textShadow: `0 0 ${8 * glowIntensity}px white, 0 0 ${20 * glowIntensity}px ${primaryColor}`,
            opacity: textOpacity,
            textTransform: "uppercase",
            whiteSpace: "nowrap",
            marginTop: "1%", // Slight optical alignment for typical sci-fi fonts
            transition: "none",
          }}
        >
          {message}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SciFiPopup;